export fn neural_network_perceptron_classifier(v:[*]const i64,n:usize,o:[*]u8,cap:usize)i64{if(n<5)return -1;const f=v[0];const s=v[1];const bias=v[2];if(f<1 or f>3 or s<1 or s>4 or bias < -10000 or bias>10000 or n!=@as(usize,@intCast(3+f+f*s)))return -1;for(0..@intCast(f))|i|{if(v[3+i] < -10000 or v[3+i]>10000)return -1;}for(3+@as(usize,@intCast(f))..n)|i|{if(v[i] < -10 or v[i]>10)return -1;}if(cap<@as(usize,@intCast(s)))return -2;for(0..@intCast(s))|j|{var z=bias;for(0..@intCast(f))|i|z+=v[3+i]*v[3+@as(usize,@intCast(f))+i*@as(usize,@intCast(s))+j];o[j]=@intFromBool(z>0);}return s;}
